class LifeWisdom {
  const LifeWisdom(this.topic, this.title, this.hinglishTitle, this.body, this.hinglishBody, this.action, this.hinglishAction);
  final String topic, title, hinglishTitle, body, hinglishBody, action, hinglishAction;
}
const realLifeWisdom = <LifeWisdom>[
  LifeWisdom('School', 'One result is not your whole story', 'Ek result tumhari poori kahani nahi', 'A mark tells you something about one attempt. Look for the skill you can practise next, without turning a number into your identity.', 'Marks ek attempt ki information hain, tumhari value nahi. Dekho kaunsa part samajhna baaki hai.', 'Choose one question you got wrong and ask how to solve it.', 'Ek galat question choose karo aur uska method samjho.'),
  LifeWisdom('School', 'You can ask a small question', 'Chhota sa question bhi puchh sakte ho', 'You do not need a perfect sentence to ask for help. Being curious is part of learning.', 'Help maangne ke liye perfect bolna zaroori nahi. Seekhne me confusion bhi aata hai.', 'Ask: “Could you explain that step once more?”', 'Bolo: “Ye step ek baar aur samjha denge?”'),
  LifeWisdom('Online', 'A feed is a selection', 'Feed poori life nahi dikhata', 'You are seeing selected moments from many people, while living every ordinary hour of your own day.', 'Dusron ke selected moments ko apne poore din se compare karna heavy pad sakta hai.', 'Mute one account that repeatedly leaves you feeling worse.', 'Ek aisa account mute karo jiske baad baar-baar bura lagta hai.'),
  LifeWisdom('Relationships', 'Listen before you fix', 'Fix karne se pehle suno', 'People sometimes need company before solutions. Ask what kind of help would feel useful.', 'Kabhi advice se pehle bas kisi ka saath chahiye hota hai. Puchh lo unhe kya chahiye.', 'Ask: “Would you like me to listen or help think of options?”', 'Puchho: “Bas sunu ya options sochne me help karu?”'),
  LifeWisdom('Work', 'Begin smaller than you planned', 'Plan se bhi chhota start karo', 'A large task becomes easier to approach when the first visible action is clear.', 'Bade task ka pehla step clear ho toh shuru karna thoda easy lag sakta hai.', 'Open the document and write one rough sentence.', 'Document kholo aur ek rough line likho.'),
  LifeWisdom('Family', 'A boundary can be kind', 'Boundary bhi pyaar se ho sakti hai', 'Being available all the time is not the only way to care. Be clear about what you can offer.', 'Har waqt available rehna hi care nahi. Jo kar sakte ho, use clearly bolo.', 'Say: “I can help after six, but not during class or work.”', 'Bolo: “Main 6 ke baad help kar sakta hu, abhi class ya work hai.”'),
  LifeWisdom('Everyday', 'Notice something ordinary', 'Kuch ordinary bhi notice karo', 'Gratitude does not require pretending the day was easy. Something comforting can exist alongside a hard day.', 'Gratitude ka matlab mushkil ko ignore karna nahi. Difficult din me bhi koi chhoti comfort ho sakti hai.', 'Name one meal, message, person or quiet moment you appreciated.', 'Ek meal, message, person ya quiet moment yaad karo.'),
  LifeWisdom('Relationships', 'Repair the moment', 'Galti ke baad repair bhi hota hai', 'A useful apology names your action without handing responsibility to the other person.', 'Achhi apology me apne action ki responsibility hoti hai, saamne wale ko blame nahi.', 'Try: “I interrupted you. I am sorry. Please finish.”', 'Try karo: “Maine beech me roka. Sorry. Tum apni baat poori karo.”'),
  LifeWisdom('School', 'Rest belongs in a study plan', 'Study plan me rest ki jagah hai', 'A plan that leaves no room for food, sleep or a break is difficult to keep.', 'Aisa plan jisme food, sleep aur break ki jagah nahi, maintain karna tough hota hai.', 'Put one short break between two study blocks.', 'Do study blocks ke beech ek chhota break rakho.'),
  LifeWisdom('Online', 'Pause before you forward', 'Forward karne se pehle ruk jao', 'A message can feel urgent and still be wrong. Sharing less can sometimes be the thoughtful action.', 'Koi message urgent lag sakta hai aur phir bhi galat ho sakta hai. Har cheez forward karna zaroori nahi.', 'Check the original source before forwarding a surprising claim.', 'Surprising claim bhejne se pehle original source check karo.'),
  LifeWisdom('Work', 'Feedback is information', 'Feedback information hai', 'Look for the part you can use. A specific suggestion is easier to act on than a label about you.', 'Feedback me useful part dhoondo. Apne baare me label banane ke bajay next action dekho.', 'Ask for one concrete example and one next step.', 'Ek clear example aur ek next step puchho.'),
  LifeWisdom('Family', 'Share one task', 'Ek kaam share karo', 'If everything depends on you, asking for a specific kind of help may be more useful than hoping someone notices.', 'Sab kuch tumhare upar ho toh specific help maangna try karo; log hamesha khud notice nahi karte.', 'Ask someone to take one clearly defined responsibility this week.', 'Is week ek clearly defined kaam kisi ke saath share karo.'),
  LifeWisdom('Everyday', 'Feelings can change without permission', 'Feelings badal sakti hain', 'You can have a grateful morning and a difficult evening. One feeling does not cancel another.', 'Subah grateful aur shaam upset ho sakte ho. Ek feeling dusri ko cancel nahi karti.', 'Write “Right now I feel…” without judging the answer.', '“Abhi main feel kar raha hu…” likho, answer ko judge mat karo.'),
  LifeWisdom('Relationships', 'Say the specific thing', 'Specific baat bolo', '“You never care” is hard to respond to. A specific moment and request can make a conversation clearer.', '“Tum kabhi care nahi karte” ke bajay ek event aur request bolna clearer ho sakta hai.', 'Describe what happened, how it felt, and one request.', 'Kya hua, kaisa laga, aur ab kya request hai—ye teen baat bolo.'),
  LifeWisdom('School', 'Belonging should not cost your safety', 'Fit hone ke liye safety mat chhodo', 'A group does not get to demand something unsafe to prove that you belong.', 'Dost hone ka proof dene ke liye unsafe cheez karna zaroori nahi.', 'If someone pressures or bullies you, speak with a trusted adult.', 'Pressure ya bullying ho toh trusted adult se baat karo.'),
  LifeWisdom('Everyday', 'Make room for a different pace', 'Apni pace ki jagah banao', 'Milestones do not arrive in the same order for everyone. Choose a step that fits your actual circumstances.', 'Sabki milestones same order me nahi aati. Apni actual situation ke hisaab se step choose karo.', 'Name one priority for this month, not five borrowed ones.', 'Is month ki apni ek priority likho, dusron ki paanch nahi.'),
  LifeWisdom('Work', 'End the day deliberately', 'Din ko ek clear ending do', 'Unfinished work can stay unfinished until the next work block. Leave yourself a clear place to restart.', 'Kaam bacha hai toh next block ke liye ek clear restart point likh do.', 'Write tomorrow’s first task, then close the work screen.', 'Kal ka pehla task likho, phir work screen band karo.'),
  LifeWisdom('Everyday', 'Reach out before you have the words', 'Perfect words se pehle reach out karo', 'You can ask for company without a complete explanation. If distress keeps interfering with daily life, qualified support can help you explore it.', 'Puri explanation ke bina bhi saath maang sakte ho. Pareshani daily life ko affect kar rahi ho toh qualified support lena theek hai.', 'Message a trusted person: “Could we talk for a few minutes?”', 'Trusted person ko bhejo: “Kuch minutes baat kar sakte hain?”'),
];
